CREATE TABLE growth_report_revisions(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,report_id TEXT NOT NULL,seq INTEGER NOT NULL,doc_json TEXT NOT NULL CHECK(json_valid(doc_json)),manifest_json TEXT NOT NULL CHECK(json_valid(manifest_json)),context_json TEXT NOT NULL CHECK(json_valid(context_json)),action TEXT NOT NULL,published_at INTEGER,publication_order INTEGER,created_at INTEGER NOT NULL,created_by TEXT NOT NULL,PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,report_id,seq),FOREIGN KEY(tenant_id,report_id) REFERENCES growth_reports(tenant_id,id));
